$:p=user/codespaces/shiny-robot-v64x5jj4v4q2x96
for i in {1..15}; do
 s=$(gh api "$p" --jq .state 2>&1) || { printf '%s\n' "$s"; exit 1; }
 printf 'STATE=%s\n' "$s"
 case "$s" in
 Available) exit 0;;
 Shutdown)
   result=$(gh api --method POST "$p/start" --jq .state 2>&1); code=$?
   printf 'START=%s\n' "$result"
   if [ "$code" -ne 0 ]; then sleep 7; else sleep 4; fi;;
 Starting|ShuttingDown) sleep 4;;
 *) exit 1;;
 esac
done
exit 1
